#include <chrono>
#include <future>
#include <stdexcept>
#include <string>
#include <thread>
#include <utility>

std::string collect(std::future<int>& result)
{
    try
    {
        return "value " + std::to_string(result.get());
    }
    catch (const std::exception& e)
    {
        return std::string{ "failed: " } + e.what();
    }
}

std::future<int> divideLater(int a, int b)
{
    return std::async(std::launch::async, [a, b]
    {
        if (b == 0)
        {
            throw std::invalid_argument{ "division by zero" };
        }
        return a / b;
    });
}

std::future<std::string> promised(std::string text, int delayMs)
{
    std::promise<std::string> promise{};
    std::future<std::string> future{ promise.get_future() };
    std::jthread worker{ [promise = std::move(promise), text = std::move(text), delayMs]() mutable
    {
        std::this_thread::sleep_for(std::chrono::milliseconds{ delayMs });
        promise.set_value(std::move(text));
    } };
    worker.detach();
    return future;
}

unitTests:
TEST("a normal result") { auto f{ divideLater(84, 2) }; CHECK_EQ(collect(f), "value 42"); }
TEST("an exception travels through the future") { auto f{ divideLater(1, 0) }; CHECK_EQ(collect(f), "failed: division by zero"); }
TEST("a promise fulfilled from another thread") { auto f{ promised("done", 40) }; CHECK(f.wait_for(std::chrono::milliseconds{ 0 }) != std::future_status::ready); CHECK_EQ(f.get(), "done"); }
TEST("several promises at once") { auto a{ promised("a", 30) }; auto b{ promised("b", 10) }; CHECK_EQ(a.get() + b.get(), "ab"); }

